schema_ddl:
CREATE TABLE ITP (
    ITEMN INT,
    PONUM INT
);
CREATE TABLE ITM (
    ITEMN INT,
    TYPE INT,
    PRIMARY KEY (ITEMN)
);
CREATE TABLE PUR (
    PONUM INT,
    ODATE INT,
    VENDN INT
);

counterexample:
INSERT INTO ITM (ITEMN) VALUES (3);
INSERT INTO ITP (ITEMN, PONUM) VALUES (3, 100), (3, 200);
INSERT INTO PUR (PONUM, ODATE, VENDN) VALUES (100, 90, 5), (200, 90, 6);

